// A general-purpose interface for all types of machines
interface Machine {
    method printDocument(doc)
    method scanDocument(doc)
    method faxDocument(doc)
}

// A simple printer that only prints
class SimplePrinter implements Machine {
    method printDocument(doc) {
        // prints
    }
    method scanDocument(doc) {
        throw Error("Not supported")
    }
    method faxDocument(doc) {
        throw Error("Not supported")
    }
}

